finalAnswer = 0

def forkliftable(y , x): #takes the coordiantes of the current character in the list and determines if it can be accessed
    surroundingPaperRolls = 0 #counter for each time our y , x subject changes
    for dy in range(-1 , 2):
        if (y + dy < 0 or y + dy > len(grid) - 1): #check if the change in y is off the grid
            continue
        for dx in range(-1 , 2): 
            if (x + dx < 0 or x + dx > len(grid[y]) - 1): #check if the change in x is off the grid
                continue 
            if (dx == 0 and dy == 0): #dont include the subject of the function in the iteration
                continue
            if (grid[y + dy][x + dx] == "@"):
                surroundingPaperRolls += 1 

    if (surroundingPaperRolls < 4):
        return True
    else:
        return False

#MAIN PROGRAM
for y in range(0 , len(grid)):
    for x in range(0 , len(grid[y])):
        if (grid[y][x] == "@"):
            if (forkliftable(y , x)):
                finalAnswer += 1
print(finalAnswer)

